import{_ as i,I as E,c as o,o as e,a3 as l,b as n,w as a,a as s,J as B,a4 as C}from"./chunks/framework.BusRvirq.js";const f=JSON.parse('{"title":"[등록 특허 백서] 웹 브라우저 동작 레코딩 기반 AI 자연어 테스트케이스 자동화","description":"웹 브라우저 동작 레코딩을 통해 LLM 기반 자연어 테스트케이스를 자동 생성하고 Playwright MCP로 실행하는 등록 완료 원천 특허 백서","frontmatter":{"title":"[등록 특허 백서] 웹 브라우저 동작 레코딩 기반 AI 자연어 테스트케이스 자동화","shortTitle":"[등록특허] 웹 레코딩 & 자연어 QA","category":"원천기술 & 특허","sort":2,"description":"웹 브라우저 동작 레코딩을 통해 LLM 기반 자연어 테스트케이스를 자동 생성하고 Playwright MCP로 실행하는 등록 완료 원천 특허 백서","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/patents/registered-web-action-recording.html"}]]},"headers":[],"relativePath":"patents/registered-web-action-recording.md","filePath":"ko/patents/registered-web-action-recording.md","lastUpdated":1791239682000}'),d={name:"patents/registered-web-action-recording.md"};function A(g,t,h,c,D,_){const r=E("Mermaid");return e(),o("div",null,[t[1]||(t[1]=l('<h1 id="웹-브라우저-동작-레코딩-기반-ai-자연어-테스트케이스-자동화" tabindex="-1">웹 브라우저 동작 레코딩 기반 AI 자연어 테스트케이스 자동화 <a class="header-anchor" href="#웹-브라우저-동작-레코딩-기반-ai-자연어-테스트케이스-자동화" aria-label="Permalink to “웹 브라우저 동작 레코딩 기반 AI 자연어 테스트케이스 자동화”">​</a></h1><blockquote><p><strong>특허 등록 번호</strong>: 특허 제10-2025-0125736호<br><strong>발명의 명칭</strong>: 웹 브라우저 동작 레코딩을 통한 AI 기반 자연어 테스트케이스 생성 및 자동 실행 시스템 및 그 방법<br><strong>출원일</strong>: 2025년 09월 04일<br><strong>특허 법적 상태</strong>: <strong>대한민국 특허청(KIPO) 정식 등록 완료</strong><br><strong>주요 연계 솔루션</strong>: <code>SyncETA</code> (웹 자율 QA 엔진), <code>SyncVerse</code></p></blockquote><hr><h2 id="_1-해결하려는-기술적-과제" tabindex="-1">1. 해결하려는 기술적 과제 <a class="header-anchor" href="#_1-해결하려는-기술적-과제" aria-label="Permalink to “1. 해결하려는 기술적 과제”">​</a></h2><p>현대 소프트웨어 개발 환경에서는 지속적 배포(CD: Continuous Deployment) 주기가 단축됨에 따라 빈번한 회귀 테스트(Regression Test) 수행이 필수적입니다. 그러나 기존의 테스트 자동화 도구(Selenium, 정적 스크립트 기반 도구)는 다음과 같은 구조적 한계가 있었습니다:</p><ol><li><strong>높은 테스트 스크립트 작성 비용</strong>: <ul><li>전문적인 프로그래밍 역량이 요구되어 비개발자 QA 인력이나 현업 기획자의 테스트 참여가 제한되었습니다.</li></ul></li><li><strong>UI 변경에 따른 스크립트 파손</strong>: <ul><li>프론트엔드 UI 클래스나 DOM 구조가 미세하게 변경되어도 기존 스크립트의 셀렉터가 깨져 대규모 수동 수정 공수가 지속적으로 발생하였습니다.</li></ul></li><li><strong>테스트케이스 관리의 가독성 부재</strong>: <ul><li>코드로 작성된 테스트 스크립트는 비즈니스 기획서와의 정합성을 한눈에 검증하기 어려워 테스트 자산의 문서화 및 이력 관리가 분리되는 사일로(Silo) 문제가 있었습니다.</li></ul></li></ol>',6)),(e(),n(C,null,{default:a(()=>[B(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20User%5B%22%EC%82%AC%EC%9A%A9%EC%9E%90%20%EC%9B%B9%20%EB%B8%8C%EB%9D%BC%EC%9A%B0%EC%A0%80%20%EC%A1%B0%EC%9E%91%22%5D%20--%3E%20Rec%5B%22%EC%8B%A4%EC%8B%9C%EA%B0%84%20%EB%B8%8C%EB%9D%BC%EC%9A%B0%EC%A0%80%20%EC%95%A1%EC%85%98%20%EB%A0%88%EC%BD%94%EB%94%A9%20(CDP%20%EA%B8%B0%EB%B0%98)%22%5D%0A%20%20%20%20Rec%20--%3E%20Norm%5B%22DOM%20%EA%B5%AC%EC%A1%B0%20%26%20%EC%8B%9C%EA%B0%81%20%ED%8A%B9%EC%A7%95%20%EB%A9%94%ED%83%80%EB%8D%B0%EC%9D%B4%ED%84%B0%20%EC%A0%95%EA%B7%9C%ED%99%94%22%5D%0A%20%20%20%20Norm%20--%3E%20LLM%5B%22LLM%20%EA%B8%B0%EB%B0%98%20%EC%A0%95%ED%98%95%20%EC%9E%90%EC%97%B0%EC%96%B4%20%ED%85%8C%EC%8A%A4%ED%8A%B8%EC%BC%80%EC%9D%B4%EC%8A%A4%20%EC%83%9D%EC%84%B1%22%5D%0A%20%20%20%20LLM%20--%3E%20NL_TC%5B%22%EC%82%AC%EB%9E%8C%EC%9D%B4%20%ED%8C%90%EB%8F%85%20%EA%B0%80%EB%8A%A5%ED%95%9C%20%EC%9E%90%EC%97%B0%EC%96%B4%20%EB%AA%85%EC%84%B8%EC%84%9C%20(%EB%8B%A8%EA%B3%84%2F%EC%9E%85%EB%A0%A5%2F%EA%B8%B0%EB%8C%80%EA%B2%B0%EA%B3%BC)%22%5D%0A%20%20%20%20NL_TC%20--%3E%20MCP%5B%22Playwright%20MCP%20(Model%20Context%20Protocol)%20%EC%9E%90%EB%8F%99%20%EC%8B%A4%ED%96%89%22%5D%0A%20%20%20%20MCP%20--%3E%20Eval%7B%22%ED%85%8C%EC%8A%A4%ED%8A%B8%20%EC%8B%A4%ED%96%89%20%EB%B0%8F%20%ED%9A%8C%EA%B7%80%20%EA%B2%80%EC%A6%9D%22%7D%0A%20%20%20%20Eval%20--%20%22%EC%84%B1%EA%B3%B5%22%20--%3E%20Report%5B%22%EA%B2%B0%EA%B3%BC%20%EB%A6%AC%ED%8F%AC%ED%8A%B8%20%EB%B0%8F%20%EC%A7%80%EC%8B%9D%20%EC%83%89%EC%9D%B8%20%EC%B6%95%EC%A0%81%22%5D%0A%20%20%20%20Eval%20--%20%22%EC%8B%A4%ED%8C%A8%2F%EC%98%88%EC%99%B8%20%EA%B0%90%EC%A7%80%22%20--%3E%20Feedback%5B%22%EC%8B%A4%ED%96%89%20%ED%94%BC%EB%93%9C%EB%B0%B1%20%EB%A3%A8%ED%94%84%20(LLM%20%ED%94%84%EB%A1%AC%ED%94%84%ED%8A%B8%20%EB%B0%8F%20%EC%8B%9C%EB%82%98%EB%A6%AC%EC%98%A4%20%EA%B0%B1%EC%8B%A0)%22%5D%0A%20%20%20%20Feedback%20--%3E%20LLM%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<hr><h2 id="_2-핵심-동작-메커니즘" tabindex="-1">2. 핵심 동작 메커니즘 <a class="header-anchor" href="#_2-핵심-동작-메커니즘" aria-label="Permalink to “2. 핵심 동작 메커니즘”">​</a></h2><p>본 등록 특허는 사용자가 웹 브라우저에서 수행하는 일상적인 조작을 캡처하여 자연어 명세서로 변환하고, 이를 표준 도구 프로토콜(Playwright MCP)을 통해 자율적으로 재실행하는 전주기 파이프라인을 포함합니다.</p><h3 id="_1단계-실시간-브라우저-동작-레코딩" tabindex="-1">1단계: 실시간 브라우저 동작 레코딩 <a class="header-anchor" href="#_1단계-실시간-브라우저-동작-레코딩" aria-label="Permalink to “1단계: 실시간 브라우저 동작 레코딩”">​</a></h3><ul><li>Chrome DevTools Protocol(CDP) 세션을 활용하여 마우스 클릭, 텍스트 타이핑, 스크롤, 드롭다운 선택, 페이지 내비게이션 등의 시계열 이벤트를 지연 없이 캡처합니다.</li><li>단순 이벤트 좌표뿐만 아니라, 이벤트가 발생한 DOM 노드의 계층 구조, 텍스트 내용, 주변 시각적 요소(라벨, 인접 텍스트 등)를 함께 정규화합니다.</li></ul><h3 id="_2단계-llm-기반-자연어-테스트케이스-자동-생성" tabindex="-1">2단계: LLM 기반 자연어 테스트케이스 자동 생성 <a class="header-anchor" href="#_2단계-llm-기반-자연어-테스트케이스-자동-생성" aria-label="Permalink to “2단계: LLM 기반 자연어 테스트케이스 자동 생성”">​</a></h3><ul><li>수집된 동작 데이터를 대규모 언어 모델(LLM)에 전달하여, 프로그래밍 코드가 아닌 정형화된 자연어 테스트케이스 형태로 자동 변환합니다.</li><li>생성된 문서는 명확한 3단 구조(테스트 단계, 입력 데이터, 검증 기대 결과)를 지니며, 일반 기획자나 관리자가 즉시 검토할 수 있는 표준 문서 양식을 갖춥니다.</li></ul><h3 id="_3단계-playwright-mcp-기반-자동-실행" tabindex="-1">3단계: Playwright MCP 기반 자동 실행 <a class="header-anchor" href="#_3단계-playwright-mcp-기반-자동-실행" aria-label="Permalink to “3단계: Playwright MCP 기반 자동 실행”">​</a></h3><ul><li>변환된 자연어 테스트케이스는 Model Context Protocol(MCP) 규격을 따르는 Playwright 실행 에이전트로 전달됩니다.</li><li>에이전트는 자연어 지시문을 분석하여 웹 브라우저의 DOM 요소와 상호작용하고, 다중 브라우저(Chrome, Edge, Firefox, WebKit) 환경에서 시나리오를 자동 실행합니다.</li></ul><h3 id="_4단계-지속적-품질-개선-피드백-루프" tabindex="-1">4단계: 지속적 품질 개선 피드백 루프 <a class="header-anchor" href="#_4단계-지속적-품질-개선-피드백-루프" aria-label="Permalink to “4단계: 지속적 품질 개선 피드백 루프”">​</a></h3><ul><li>테스트 실행 결과와 실패 로그, 화면 스냅샷을 수집하여 LLM의 프롬프트 및 컨텍스트 메모리에 피드백합니다.</li><li>동일한 UI 패턴에 대해 더 강건하고 유지보수성이 높은 테스트케이스가 생성되도록 모델의 생성 규칙을 지속적으로 고도화합니다.</li></ul><hr><h2 id="_3-선행기술-대비-정량적-차별성" tabindex="-1">3. 선행기술 대비 정량적 차별성 <a class="header-anchor" href="#_3-선행기술-대비-정량적-차별성" aria-label="Permalink to “3. 선행기술 대비 정량적 차별성”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">비교 항목</th><th style="text-align:left;">종래의 스크립트 도구 (Selenium 등)</th><th style="text-align:left;">정적 레코더 도구</th><th style="text-align:left;">본 등록 특허 (제10-2025-0125736호)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>테스트 표현 형식</strong></td><td style="text-align:left;">Java/Python 프로그래밍 코드</td><td style="text-align:left;">단순 좌표 또는 취약한 XPath 나열</td><td style="text-align:left;"><strong>사람이 읽는 정형 자연어 명세서</strong></td></tr><tr><td style="text-align:left;"><strong>작성 난이도</strong></td><td style="text-align:left;">전문 개발 역량 필수</td><td style="text-align:left;">조작은 쉬우나 유지보수 불가</td><td style="text-align:left;"><strong>일반 사용자 조작 기반 자동 생성</strong></td></tr><tr><td style="text-align:left;"><strong>실행 엔진 연동</strong></td><td style="text-align:left;">고정된 전용 드라이버</td><td style="text-align:left;">독자적 매크로 엔진</td><td style="text-align:left;"><strong>표준 Playwright MCP 프로토콜 기반</strong></td></tr><tr><td style="text-align:left;"><strong>품질 진화 체계</strong></td><td style="text-align:left;">수동 코드 수정</td><td style="text-align:left;">정적 실행 반복</td><td style="text-align:left;"><strong>실행 피드백 기반 LLM 생성 품질 지속 개선</strong></td></tr></tbody></table><hr><h2 id="_4-모바일-특허와의-연계-및-풀스택-자율-qa-체계" tabindex="-1">4. 모바일 특허와의 연계 및 풀스택 자율 QA 체계 <a class="header-anchor" href="#_4-모바일-특허와의-연계-및-풀스택-자율-qa-체계" aria-label="Permalink to “4. 모바일 특허와의 연계 및 풀스택 자율 QA 체계”">​</a></h2><p>본 등록 특허는 데스크톱 웹 환경을 전담하며, 추가 출원 준비 중인 <strong>특허 제21호(모바일 제스처 레코딩 및 AI 자연어 테스트케이스 자동화)</strong>와 결합하여 <code>SyncETA</code>의 &#39;웹 + 모바일&#39; 통합 자율 QA 포트폴리오를 완성합니다.</p><ul><li><strong>웹 영역 (등록 특허)</strong>: CDP 기반 브라우저 액션 레코딩 ➔ Playwright MCP 자동 실행.</li><li><strong>모바일 영역 (특허 21호)</strong>: 터치 궤적 정규화 벡터 ➔ 이종 디바이스 팜(Android/iOS) 적응형 병렬 실행.</li><li>두 특허의 유기적 결합을 통해 기업은 단일 플랫폼 내에서 웹 포털부터 모바일 네이티브 앱까지 단일화된 자연어 체계로 품질 검증을 수행할 수 있습니다.</li></ul>',18))])}const m=i(d,[["render",A]]);export{f as __pageData,m as default};
